#!/usr/bin/env node
// Build the ecosystem maps in ARCHITECTURE.md: one Mermaid diagram per view of how the code
// repos work together. Views, systems, edges, and the snapshot that each repo's edges were
// checked at come from ecosystem.json; the repos come from estate.json (a repo with
// "docs": true is docs, not code, and stays off the maps). Each map sits between its BEGIN and
// END markers; the rest of ARCHITECTURE.md is edited text.
// Usage: node build-ecosystem-maps.mjs           rewrite the maps
//        node build-ecosystem-maps.mjs --check   exit 1 if a map is stale (CI)
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { EM_DASH, loadEstate, parseJson, readDocsFile, replaceMarked, root } from "./estate.mjs";

const SCRIPT = ".github/scripts/build-ecosystem-maps.mjs";
const DOC = "ARCHITECTURE.md";
const begin = (view) => `<!-- BEGIN ecosystem map ${view}: generated by ${SCRIPT} from estate.json and ecosystem.json. Do not edit by hand. -->`;
const end = (view) => `<!-- END ecosystem map ${view} -->`;
const ARROWS = { plain: "-->", inferred: "-.->", both: "<-->" };
const SHAPES = { database: ['[("', '")]'], box: ['["', '"]'] };
const DIRECTIONS = ["TB", "LR"];

const check = process.argv.includes("--check");
const { repos, errors } = loadEstate();

// Check ecosystem.json in both directions, and return it only if it is valid. Each edge names
// a code repo or a system at each end, a known view and arrow, a label, and its evidence. Each
// view, system, and code repo is on a map. The edges of each code repo were checked at its
// current snapshot, so a regeneration fails the check until a person checks them again.
function validEcosystem(eco, codeRepos) {
  const before = errors.length;
  const fail = (message) => errors.push(`ecosystem.json: ${message}`);
  for (const key of ["views", "systems", "edges"]) if (!Array.isArray(eco?.[key])) fail(`${key} must be a list`);
  if (errors.length > before) return null;
  const viewIds = new Set(eco.views.map((v) => v.id));
  const systemIds = new Set(eco.systems.map((s) => s.id));
  for (const v of eco.views) if (!DIRECTIONS.includes(v.direction)) fail(`view "${v.id}" has an unknown direction "${v.direction}"`);
  for (const s of eco.systems) if (!SHAPES[s.shape]) fail(`system "${s.id}" has an unknown shape "${s.shape}"`);
  const onMap = new Set();
  eco.edges.forEach((e, i) => {
    const at = `edge ${i + 1} (${e.from} -> ${e.to})`;
    for (const end of ["from", "to"]) {
      const n = e[end];
      if (!codeRepos.has(n) && !systemIds.has(n)) fail(`${at}: ${end} ${n} is not a code repo or a system`);
      onMap.add(n);
    }
    if (!viewIds.has(e.view)) fail(`${at}: unknown view "${e.view}"`);
    if (!ARROWS[e.arrow ?? "plain"]) fail(`${at}: unknown arrow "${e.arrow}"`);
    // Mermaid ends a label at a double quote; this repo's text uses no em dash.
    if (!e.label || e.label.includes('"') || e.label.includes(EM_DASH)) fail(`${at}: the label must be set, with no double quote and no em dash`);
    if (!e.evidence) fail(`${at}: has no evidence`);
  });
  for (const v of viewIds) if (!eco.edges.some((e) => e.view === v)) fail(`view "${v}" has no edges`);
  for (const s of systemIds) if (!onMap.has(s)) fail(`system "${s}" is on no map`);
  for (const [name, { sha }] of codeRepos) {
    if (!onMap.has(name)) fail(`${name} is on no map: add an edge`);
    // A short commit, as in the README index: a full one looks like a key to the secret scanners.
    const checked = eco.checkedAt?.[name];
    if (!checked) fail(`checkedAt.${name} is missing`);
    else if (!/^[0-9a-f]{7}$/.test(checked)) fail(`checkedAt.${name} must be the first 7 characters of a commit`);
    else if (!sha.startsWith(checked)) {
      fail(`checkedAt.${name} is ${checked.slice(0, 7)}, but repos/${name}/meta.json is ${sha.slice(0, 7)}: check the edges of ${name} again, then update checkedAt`);
    }
  }
  return errors.length > before ? null : eco;
}

const codeRepos = new Map(repos.filter((r) => !r.docs).map((r) => [r.name, r]));
const ecosystem = validEcosystem(readDocsFile("ecosystem.json", errors, parseJson), codeRepos);

// Mermaid ids: letters, digits, and "_" only. A store of data is a cylinder.
const mermaidId = (name) => `n_${name.replace(/[^A-Za-z0-9]/g, "_")}`;
function node(name) {
  const system = ecosystem.systems.find((s) => s.id === name);
  const [open, close] = SHAPES[system?.shape ?? "box"];
  return `${mermaidId(name)}${open}${system ? system.name : name}${close}`;
}

function diagram(view) {
  const edges = ecosystem.edges.filter((e) => e.view === view.id);
  const names = [...new Set(edges.flatMap((e) => [e.from, e.to]))];
  return [
    "```mermaid",
    `flowchart ${view.direction}`,
    ...names.map((n) => `  ${node(n)}`),
    ...edges.map((e) => `  ${mermaidId(e.from)} ${ARROWS[e.arrow ?? "plain"]}|"${e.label}"| ${mermaidId(e.to)}`),
    "```",
  ].join("\n");
}

const doc = readDocsFile(DOC, errors);
let next = doc;
if (doc !== null && ecosystem) {
  const viewIds = new Set(ecosystem.views.map((v) => v.id));
  for (const [, view] of doc.matchAll(/<!-- BEGIN ecosystem map (\S+):/g)) {
    if (!viewIds.has(view)) errors.push(`${DOC} has a map block for "${view}", which is not a view in ecosystem.json`);
  }
  for (const view of ecosystem.views) {
    const markers = { begin: begin(view.id), end: end(view.id), what: `${view.id} map` };
    next = replaceMarked(DOC, next, markers, diagram(view), errors);
  }
}

if (errors.length) {
  for (const e of errors) console.error(`error: ${e}`);
  process.exit(1);
}

const counts = `${ecosystem.views.length} views, ${ecosystem.edges.length} edges`;
if (check) {
  if (next !== doc) {
    console.error(`error: the ecosystem maps in ${DOC} are stale. Run: node ${SCRIPT}`);
    process.exit(1);
  }
  console.log(`ecosystem maps are current (${counts})`);
} else {
  writeFileSync(join(root, DOC), next);
  console.log(`wrote the ecosystem maps to ${DOC} (${counts})`);
}
